var e=[{title:`Porque é que a balança se mexe`,text:`A comida e a bebida, a hidratação, o sódio, o glicogénio armazenado e outros processos normais alteram o seu peso corporal de dia para dia. Uma leitura alta ou baixa não lhe diz nada de fiável sobre o músculo ou a gordura. O exercício pode alterar a sua composição corporal mesmo quando o seu peso total quase não se mexe.`},{title:`Meça sempre da mesma forma`,text:`Se se pesar, use a mesma balança e uma rotina semelhante em vez de horas aleatórias. Uma média semanal costuma ser mais útil do que uma só leitura. A cintura e outras medições com fita só são comparáveis se usar os mesmos pontos de referência do corpo e a mesma tensão da fita.`},{title:`As fotografias são opcionais`,text:`As fotografias de progresso podem mostrar alterações na postura ou no aspeto, mas a iluminação, o ângulo da câmara e a roupa afetam-nas muito. Não precisa delas se o seu foco for a condição física ou a força, e podem não ajudar se tiver preocupações com a imagem corporal ou a alimentação.`},{title:`Condição física e peso são coisas separadas`,text:`Mover-se melhor, durar mais tempo e ficar mais forte são resultados reais, seja qual for o seu tamanho. Se estiver preocupado com uma alteração inesperada do peso ou com uma condição médica, fale com um profissional de saúde.`},{title:`Usar o TrainUp`,text:`O ecrã Hoje tem um registo do peso corporal, e usá-lo ou não é consigo. Leia-o como uma tendência ao longo de várias semanas. O TrainUp não trata o peso corporal como uma medida de condição física e não define metas de perda de peso.`}];var s=[{label:`CDC: peso saudável e atividade`,url:`https://www.cdc.gov/healthy-weight-growth/losing-weight/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:e,sources:s};export{r as default,e as sections,s as sources};